// Deja una lista corta y variada de candidatas para la IA:
// sin titulares repetidos y con un máximo por fuente para que ninguna lo acapare.
const cfg = $('Configuración').first().json;
const MAX_POR_FUENTE = 6;
const MIN_TEXTO = 80; // sin texto suficiente, la IA solo podría parafrasear el titular

const filas = $input.all().map(i => i.json).filter(r => r.url && r.title && (r.texto || '').length >= MIN_TEXTO);
const vistos = new Set();
const porFuente = {};
const candidatas = [];

for (const r of filas) {
  const clave = r.title.toLowerCase().normalize('NFD').replace(/[^a-z0-9 ]/g, '').replace(/\s+/g, ' ').trim().slice(0, 80);
  if (vistos.has(clave)) continue;
  vistos.add(clave);
  porFuente[r.source] = (porFuente[r.source] || 0) + 1;
  if (porFuente[r.source] > MAX_POR_FUENTE) continue;
  candidatas.push({
    n: candidatas.length + 1,
    titulo: r.title,
    url: r.url,
    fuente: r.source,
    fecha: new Date(r.published_at).toISOString(),
    texto: r.texto || '',
  });
}

if (candidatas.length === 0) return []; // nada nuevo en el periodo: no se envía nada

const instrucciones = [
  `Eres el editor de un boletín en español sobre inteligencia artificial. Recibes noticias numeradas de los últimos ${cfg.dias} días.`,
  'Criterio para elegir: lo más útil para quien construye con IA (lanzamientos, herramientas, técnicas, cambios que afectan al trabajo técnico). Descarta las que repiten tema, las notas de versión menores y el contenido promocional.',
  'Devuelve:',
  `- "destacadas": las ${cfg.destacadas} noticias más importantes, de más a menos. Para cada una:`,
  '  - id: el número entre corchetes, exacto.',
  '  - titulo: el titular en español, máximo 70 caracteres.',
  '  - resumen: una o dos frases en español sobre qué ha pasado, usando solo lo que dice el texto. No añadas datos que no estén en el texto. Si usas cifras, cópialas tal como aparecen en el original.',
  '  - por_que_importa: una frase para alguien que dirige un negocio o una pequeña empresa: qué le puede suponer en la práctica. Escríbela en forma impersonal (nunca «podrás» ni «puedes»). Solo lo que se deduce del texto: no prometas resultados; si el texto no permite deducir un efecto práctico, di a qué tipo de empresa le conviene seguir el tema. Sin tecnicismos y sin cifras que no estén en el texto.',
  `- "tambien": entre 3 y ${cfg.tambien} noticias más, distintas de las destacadas, cada una con id y titulo (máximo 70 caracteres).`,
  'Responde solo con JSON.',
].join('\n');

const lista = candidatas.map(c => `[${c.n}] (${c.fuente}) ${c.titulo}\n${c.texto}`).join('\n\n');

return [{ json: { candidatas, instrucciones, lista, fuentes: Object.keys(porFuente).length } }];

