// Saca el JSON de la respuesta de Gemini. Si no hay JSON válido con noticias,
// el error sale por la salida de error y el resumen lo redacta Groq.
const r = $input.first().json;
const texto = (r.candidates?.[0]?.content?.parts || [])
  .filter(p => !p.thought)
  .map(p => p.text || '')
  .join('');
const datos = JSON.parse(texto);
if (!Array.isArray(datos.destacadas) || datos.destacadas.length === 0) {
  throw new Error('Gemini no devolvió noticias destacadas');
}
return [{ json: { ...datos, modelo: $('Configuración').first().json.modelo_gemini } }];

