const r = $input.first().json;
const datos = JSON.parse(r.choices?.[0]?.message?.content || '');
if (!Array.isArray(datos.destacadas) || datos.destacadas.length === 0) {
  throw new Error('Groq no devolvió noticias destacadas');
}
return [{ json: { ...datos, modelo: $('Configuración').first().json.modelo_groq } }];

// Comprueba lo que ha escrito la IA antes de enviarlo:
// - el enlace, la fuente y la fecha no los escribe la IA: salen de la base de datos por el id;
// - una noticia con una cifra que no aparece en su texto original se descarta.
// Después monta el mensaje en HTML de Telegram: 3 destacadas y el resto en una línea.
const cfg = $('Configuración').first().json;
const prep = $('Preparar candidatas').first().json;
const datos = $input.first().json;

const NOMBRES = {
  ahead_of_ai: 'Ahead of AI', import_ai: 'Import AI', latent_space: 'Latent Space',
  simon_willison: 'Simon Willison', one_useful_thing: 'One Useful Thing',
  openai_news: 'OpenAI', n8n_releases: 'n8n',
};
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const attr = (s) => esc(s).replace(/"/g, '&quot;');
// "15,000", "15.000" y "15 000" cuentan como la misma cifra: se comparan solo los dígitos.
const cifras = (s) => (String(s ?? '').match(/\d{1,3}(?:[   .,]\d{3})+(?:[.,]\d+)?|\d+(?:[.,]\d+)?/g) || [])
  .map(n => n.replace(/\D/g, ''));
const ddmm = (d) => `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}`;
const fuente = (c) => esc(NOMBRES[c.fuente] || c.fuente);

const porId = new Map(prep.candidatas.map(c => [c.n, c]));
const usadas = new Set();
const descartadas = [];

function validar(lista, campos, maximo) {
  const ok = [];
  for (const n of lista || []) {
    if (ok.length >= maximo) break;
    const c = porId.get(Number(n.id));
    if (!c) { descartadas.push({ id: n.id, motivo: 'id que no existe en la lista' }); continue; }
    if (usadas.has(c.n)) continue;
    if (campos.some(k => !n[k])) { descartadas.push({ id: c.n, motivo: 'faltan campos' }); continue; }
    const originales = new Set(cifras(`${c.titulo} ${c.texto}`));
    const inventadas = cifras(campos.map(k => n[k]).join(' ')).filter(x => !originales.has(x));
    if (inventadas.length) {
      descartadas.push({ id: c.n, url: c.url, motivo: `cifras que no están en el original: ${inventadas.join(', ')}` });
      continue;
    }
    usadas.add(c.n);
    ok.push({ c, n });
  }
  return ok;
}

const destacadas = validar(datos.destacadas, ['titulo', 'resumen', 'por_que_importa'], cfg.destacadas);
const tambien = validar(datos.tambien, ['titulo'], cfg.tambien);

if (destacadas.length === 0) {
  throw new Error(`Ninguna noticia destacada pasó la validación: ${JSON.stringify(descartadas)}`);
}

const hoy = new Date();
const modelo = String(datos.modelo).startsWith('gemini') ? 'Gemini' : 'gpt-oss en Groq';

const bloqueDestacada = ({ c, n }, i) => [
  `<b>${i + 1}. ${esc(n.titulo)}</b>`,
  esc(n.resumen),
  `→ ${esc(n.por_que_importa)}`,
  `<a href="${attr(c.url)}">${fuente(c)} · ${ddmm(new Date(c.fecha))}</a>`,
].join('\n');

const lineaTambien = ({ c, n }) => `• <a href="${attr(c.url)}">${esc(n.titulo)}</a> · ${fuente(c)}`;

let nTambien = tambien.length;
let html;
do {
  const partes = [
    `<b>Noticiero IA · ${ddmm(new Date(hoy - cfg.dias * 864e5))} – ${ddmm(hoy)}</b>`,
    '<b>LO MÁS IMPORTANTE</b>',
    ...destacadas.map(bloqueDestacada),
  ];
  if (nTambien > 0) partes.push(['<b>TAMBIÉN</b>', ...tambien.slice(0, nTambien).map(lineaTambien)].join('\n'));
  partes.push(`<i>${destacadas.length + nTambien} noticias · redactado con ${modelo}</i>`);
  html = partes.join('\n\n');
  if (html.length <= 4000) break;
  nTambien--;
} while (nTambien >= 0);

return [{
  json: {
    digest_type: 'bisemanal',
    content_html: html,
    model: datos.modelo,
    news_count: destacadas.length + Math.max(nTambien, 0),
    discarded: JSON.stringify(descartadas),
  },
}];
